        WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.conname = 'mcp_call_log_tool_check')
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['get_status', 'list_deals', 'get_deal', 'get_deal_checklists', 'list_all_deals', 'update_todo', 'add_todo', 'remove_todo', 'restore_todo', 'find_people', 'list_todos']::text[]) x),
    'outcome_check_unchanged', (SELECT pg_get_constraintdef(c.oid) FROM pg_constraint c WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.conname = 'mcp_call_log_outcome_check')
        IS NOT DISTINCT FROM (SELECT def FROM pg_temp.p4263p8_check_before WHERE name = 'mcp_call_log_outcome_check'),
    'check_count_unchanged', (SELECT count(*) FROM pg_constraint c WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.contype = 'c') = (SELECT count(*) FROM pg_temp.p4263p8_check_before),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118150000')) INTO v;
  IF v -> 'bodies' <> '{}'::jsonb OR (v ->> 'readers_ok')::boolean IS NOT TRUE OR (v ->> 'readers_api_grants')::int <> 0
     OR (v ->> 'readers_postgres')::boolean IS NOT TRUE OR (v ->> 'tools_other_grants')::int <> 0 OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE
