                                                                       left(btrim(coalesce(e ->> 'e164', '')), 1) = '+' AS plus) z
                                          WHERE CASE WHEN z.plus THEN z.sd WHEN char_length(z.sd) = 10 THEN '1' || z.sd ELSE z.sd END = p_phone)) /*MATCH:phone*/
       ORDER BY s.id /*ORDER:fp*/
       LIMIT 101),
    r AS (
      SELECT h.id, row_number() OVER (ORDER BY h.id) AS rk, jsonb_build_object(
          'person_id', h.id,
          'details_withheld', h.w,
          'name', h.s_name,
          'company', h.s_company,
          'role', h.s_role,
          'role_category', h.s_role_category,
          'specific_role', h.s_specific_role,
          'is_primary', h.is_primary,
          'emails', h.s_emails,
