             public._mcp_clean(l.role_category, 100) AS s_role_category,
             public._mcp_clean(l.specific_role, 100) AS s_specific_role,
             CASE WHEN l.w THEN '[]'::jsonb /*WITHHELD:emails*/ ELSE coalesce((
