  (SELECT count(*) FROM public.mcp_call_log WHERE tool IN ('find_people', 'list_todos')) AS log_rows,
  (SELECT count(*) FROM public.mcp_rate_counters WHERE bucket LIKE 'find\_people\_user:%') AS counters;
DELETE FROM public.mcp_call_log WHERE tool IN ('find_people', 'list_todos');
DELETE FROM public.mcp_rate_counters WHERE bucket LIKE 'find\_people\_user:%';
DROP FUNCTION IF EXISTS public.mcp_find_people(text, bytea, text, text, text, text, text, text, text);
DROP FUNCTION IF EXISTS public.mcp_list_todos(text, bytea, text, text, text, text, text, boolean, boolean, text);
DROP FUNCTION IF EXISTS public._mcp_r_find_people(text, text, uuid, text, text, uuid);
DROP FUNCTION IF EXISTS public._mcp_r_list_todos(text, text, date, date, boolean, boolean, date, uuid);
SET LOCAL lock_timeout = '3s';
DO $chk4263p8r$
DECLARE
  v_name text;
BEGIN
  FOR v_name IN
    SELECT c.conname FROM pg_catalog.pg_constraint c
     WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.contype = 'c'
       AND c.conkey = ARRAY[(SELECT a.attnum FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'public.mcp_call_log'::regclass AND a.attname = 'tool')]
  LOOP
    EXECUTE format('ALTER TABLE public.mcp_call_log DROP CONSTRAINT %I', v_name);
  END LOOP;
END
$chk4263p8r$;
ALTER TABLE public.mcp_call_log ADD CONSTRAINT mcp_call_log_tool_check
  CHECK (tool IS NULL OR tool IN ('get_status', 'list_deals', 'get_deal', 'get_deal_checklists', 'list_all_deals', 'update_todo', 'add_todo', 'remove_todo', 'restore_todo'));
DELETE FROM supabase_migrations.schema_migrations WHERE version = '20261118150000';

DO $post4263p8r$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'new_left', (SELECT count(*) FROM unnest(ARRAY['public._mcp_r_find_people(text,text,uuid,text,text,uuid)', 'public._mcp_r_list_todos(text,text,date,date,boolean,boolean,date,uuid)', 'public.mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'public.mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)']) s WHERE to_regprocedure(s) IS NOT NULL),
    'anon_mcp_15', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text COLLATE "C"), '{}') FROM pg_proc p
        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'other_functions_changed', (SELECT count(*) FROM pg_temp.p4263p8r_fn_before b
         WHERE NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.oid::regprocedure::text = b.sig
                             AND md5(p.prosrc) = b.src_md5 AND p.proacl::text IS NOT DISTINCT FROM b.acl AND p.proconfig IS NOT DISTINCT FROM b.config
                             AND p.prosecdef = b.secdef AND p.proowner = b.owner AND p.provolatile = b.vol)),
    'tool_check', (SELECT array_agg(m[1] ORDER BY m[1] COLLATE "C") FROM pg_constraint c, regexp_matches(pg_get_constraintdef(c.oid), '''([a-z_]+)''', 'g') m
        WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.conname = 'mcp_call_log_tool_check')
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['get_status', 'list_deals', 'get_deal', 'get_deal_checklists', 'list_all_deals', 'update_todo', 'add_todo', 'remove_todo', 'restore_todo']::text[]) x),
    'outcome_check_unchanged', (SELECT pg_get_constraintdef(c.oid) FROM pg_constraint c WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.conname = 'mcp_call_log_outcome_check')
        IS NOT DISTINCT FROM (SELECT def FROM pg_temp.p4263p8r_check_before WHERE name = 'mcp_call_log_outcome_check'),
    'check_count_unchanged', (SELECT count(*) FROM pg_constraint c WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.contype = 'c') = (SELECT count(*) FROM pg_temp.p4263p8r_check_before),
    'log_rows_deleted', (SELECT log_rows FROM pg_temp.p4263p8r_counts),
    'day_counters_deleted', (SELECT counters FROM pg_temp.p4263p8r_counts),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118150000')) INTO v;
  IF (v ->> 'new_left')::int <> 0 OR (v ->> 'anon_mcp_15')::boolean IS NOT TRUE OR (v ->> 'other_functions_changed')::int <> 0
     OR (v ->> 'tool_check')::boolean IS NOT TRUE OR (v ->> 'outcome_check_unchanged')::boolean IS NOT TRUE
     OR (v ->> 'check_count_unchanged')::boolean IS NOT TRUE OR (v ->> 'ledger')::int <> 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261118150000 FAILED, nothing changed: %', v;
  END IF;
  RAISE NOTICE 'ROLLBACK POST-CHECK 20261118150000 OK: %', v;
END
$post4263p8r$;

DO $after$
BEGIN
  PERFORM pg_temp.unrate();
  PERFORM pg_temp.rec('rb_get_deal_still_answers', to_jsonb(pg_temp.ws(pg_temp.w(pg_temp.q_gd(1, pg_temp.id('DA1'))))));
  PERFORM pg_temp.rec('rb_find_people_gone', to_jsonb(to_regprocedure('public.mcp_find_people(text,bytea,text,text,text,text,text,text,text)') IS NULL));
  PERFORM pg_temp.rec('t_end', to_jsonb(clock_timestamp()));
  RAISE EXCEPTION 'P8_RESULT %', (SELECT jsonb_object_agg(k, v) FROM pg_temp.p8_out);
END
$after$;
